        if(ReviewBusy(o)){notice(o,"Finish the current recording/edit first.");return;}var clip=Session(o).Call("primary_clip").AsGodotObject();var actor=Session(o).Call("primary_actor").AsGodotObject();if(clip==null||actor==null)return;var values=Dict(actor,"values");if(!Session(o).Call("can_edit",clip.Get("id")).AsBool()||Get(values,"reverse",false).AsBool()||Get(values,"loop",false).AsBool()){notice(o,"Choose an unlocked forward, non-looped dialogue clip.");return;}if(Get(Get(values,"automation",new Settings()).AsGodotDictionary(),"volume_db",new GArray()).AsGodotArray().Count>0){notice(o,"Breath review creates clip gain automation. Bake or remove the existing gain curve first so its interpolation is not changed.");return;}var source=Get(values,"audio");double start=clip.Get("source_offset").AsDouble(),seconds=clip.Get("duration").AsDouble()*clip.Get("playback_speed").AsDouble();long owner=unchecked((long)Session(o).GetInstanceId()),document=unchecked((long)Document(o).GetInstanceId());string id=clip.Get("id").AsString(),identity=analysis_identity(actor);Work(o,"breath_review",Session(o).Get("revision").AsInt64(),job=>{using var restoration=new AudioRestorationOperations();var result=restoration.breath_candidates(source,start,seconds,job);result["owner"]=owner;result["document"]=document;result["clip_id"]=id;result["identity"]=identity;return result;});
