    public void breath_review_ready(Control o,Settings result)
    {
        if(result["owner"].AsInt64()!=unchecked((long)Session(o).GetInstanceId())||result["document"].AsInt64()!=unchecked((long)Document(o).GetInstanceId()))return;var clip=Document(o).Call("clip_for_id",result["clip_id"].AsString()).AsGodotObject();var actor=Document(o).Call("actor_for_clip",result["clip_id"].AsString()).AsGodotObject();if(clip==null||actor==null||analysis_identity(actor)!=result["identity"].AsString())return;var owner=Session(o);var document=Document(o);long revision=owner.Get("revision").AsInt64();var dialog=window(o,"Review possible breath/noise regions",new Vector2I(720,540));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();double reduction=9;label(host,"Heuristic candidates: short, low-level, noise-like passages—not speech recognition. Sibilants and room noise can also match. Nothing is selected automatically. Audition each candidate and check only breaths you want reduced. Source files are untouched; gain automation remains editable.");NumberAction(o,host,"Reduction (dB)",9,0,30,.5,value=>reduction=value);var tree=new Tree{SizeFlagsVertical=Control.SizeFlags.ExpandFill,HideRoot=true};host.AddChild(tree);var root=tree.CreateItem();var rows=new System.Collections.Generic.List<TreeItem>();var candidates=result["regions"].AsGodotArray();foreach(var raw in candidates){var region=raw.AsGodotDictionary();var item=tree.CreateItem(root);item.SetCellMode(0,TreeItem.TreeCellMode.Check);item.SetEditable(0,true);item.SetChecked(0,false);item.SetText(0,DecimalText(region["start"].AsDouble())+"–"+DecimalText(region["end"].AsDouble())+" source seconds");rows.Add(item);}if(rows.Count==0)label(host,"No candidates matched the conservative detector. Use waveform gain automation to edit other breaths manually.");var actions=new HFlowContainer();host.AddChild(actions);ActionButton(actions,"Audition selected source region",()=>{if(Session(o)!=owner||Document(o)!=document||owner.Get("revision").AsInt64()!=revision)return;int index=rows.IndexOf(tree.GetSelected());if(index<0)return;var region=candidates[index].AsGodotDictionary();var stream=workspace_source(Get(Dict(actor,"values"),"audio"));double start=region["start"].AsDouble(),seconds=region["end"].AsDouble()-start;Work(o,"audition",0,_=>{using var source=new AudioSourceCacheOperations();var decoded=source.decode(stream,24000,start,seconds,1);if(Get(decoded,"error","").AsString().Length>0)return decoded;return new Settings{["stream"]=source.to_wav(decoded["samples"].AsVector2Array(),24000,true)};});});ActionButton(actions,"Reduce checked regions · one Undo",()=>{if(Session(o)!=owner||Document(o)!=document||owner.Get("revision").AsInt64()!=revision||!owner.Call("can_edit",clip.Get("id")).AsBool()||analysis_identity(actor)!=result["identity"].AsString()){notice(o,"The dialogue changed. Review it again.");return;}var regions=new System.Collections.Generic.List<Vector2>();double offset=clip.Get("source_offset").AsDouble(),speed=clip.Get("playback_speed").AsDouble();for(int index=0;index<rows.Count;index++)if(rows[index].IsChecked(0)){var region=candidates[index].AsGodotDictionary();regions.Add(new Vector2((float)((region["start"].AsDouble()-offset)/speed),(float)((region["end"].AsDouble()-offset)/speed)));}if(regions.Count==0)return;var values=Dict(actor,"values");var original=Get(Get(values,"automation",new Settings()).AsGodotDictionary(),"volume_db",new GArray()).AsGodotArray().Duplicate(true);var times=new System.Collections.Generic.SortedSet<double>{0,clip.Get("duration").AsDouble()};foreach(var raw in original)times.Add(raw.AsGodotDictionary()["time"].AsDouble());foreach(var region in regions){double edge=Math.Min(.025,(region.Y-region.X)*.25);foreach(double time in new[]{region.X,region.X+edge,region.Y-edge,region.Y})times.Add(time);}if(times.Count>10000){notice(o,"The combined automation curve would exceed 10,000 points.");return;}var points=new GArray();var schema=GD.Load<CSharpScript>("res://Workspaces/AudioWorkspace/KiwiAudioEditSession.cs");foreach(double time in times){double amount=0;foreach(var region in regions){double edge=Math.Min(.025,(region.Y-region.X)*.25);amount=Math.Max(amount,Math.Min(Math.Clamp((time-region.X)/edge,0,1),Math.Clamp((region.Y-time)/edge,0,1)));}points.Add(new Settings{["time"]=time,["value"]=schema.Call("automation_value",original,time,Get(values,"volume_db",0).AsDouble()).AsDouble()-reduction*amount,["curve"]="linear"});}SessionAction(o,"Reviewed breath reduction",()=>{var curves=Get(values,"automation",new Settings()).AsGodotDictionary().Duplicate(true);curves["volume_db"]=points;values[new StringName("automation")]=curves;});Field<AudioStreamPlayer>(o,"preview_player").Stop();windowNode.QueueFree();});
    }
    public void review_dialogue_batch(Control o)
    {
        if(ReviewBusy(o)){notice(o,"Finish recording or the current adjustment before dialogue review.");return;}var ids=Items(Session(o),"selected_ids").Duplicate();foreach(var id in ids){string reason=Session(o).Call("_silence_reason",id).AsString();if(reason.Length>0){notice(o,reason);return;}}var snapshot=Document(o).Call("snapshot").As<RefCounted>();long owner=unchecked((long)Session(o).GetInstanceId()),document=unchecked((long)Document(o).GetInstanceId()),revision=Session(o).Get("revision").AsInt64();double threshold=o.Get("_silence_threshold").AsDouble(),minimum=o.Get("_silence_minimum").AsDouble();Work(o,"dialogue_batch",revision,job=>{using var batch=new AudioDialogueBatchOperations();var result=batch.analyze(snapshot,ids,threshold,minimum,job);result["owner"]=owner;result["document"]=document;return result;});
    }
    public void dialogue_batch_ready(Control o,Settings result)
