.Check);item.SetEditable(0,true);item.SetChecked(0,true);item.SetText(0,"Remove quiet region");item.SetText(1,DecimalText(region["start"].AsDouble()));item.SetText(2,DecimalText(region["end"].AsDouble()));group.Add(item);}rows.Add(group);}var summary=new Label{AutowrapMode=TextServer.AutowrapMode.WordSmart};host.AddChild(summary);ActionButton(host,"Apply reviewed queue · one Undo",()=>{if(Session(o)!=owner||Document(o)!=document||owner.Get("revision").AsInt64()!=revision||Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()||Recording(o).Get("active").AsBool()||Recording(o).Call("has_pending").AsBool()){summary.Text="The document changed. Close and review again.";return;}var choices=new GArray();foreach(var group in rows){var chosen=new GArray();for(int index=0;index<group.Count;index++)if(group[index].IsChecked(0))chosen.Add(index);choices.Add(chosen);}using var apply=new AudioDialogueBatchOperations();var applied=apply.apply(owner,plans,choices,scope,overlap);string problem=Get(applied,"error","").AsString();if(problem.Length>0){summary.Text=problem;return;}Field<Label>(o,"status").Text="Dialogue queue removed "+DecimalText(Get(applied,"removed",0).AsDouble())+" seconds with overlapping joins.";windowNode.QueueFree();});
